<script>
import TitleLine from './TitleLine'
import { getSuppleUrl, getHuiOneinfo, getRgHuione, getOrder } from '@/api/user'
import QRCode from 'qrcodejs2'
export default {
  components: {
    TitleLine
  },
  props: {
    currentValue: {
      type: String,
      default: '哈希一分大小'
    }
  },
  data() {
    return {
      imgUrl: '',
      title: '充值',
      nameValue: '',
      addressValue: '',
      addressValueHw: '',
      tabList: [{ tab: 'USDT' }, { tab: '美金-汇旺' }],
      payModeList: [{ payMode: '汇旺扫码' }, { payMode: '汇旺转账' }],
      tabColor: 0,
      payMode: 0,
      mons: 0,
      monsList: [{ mons: '100' }, { mons: '200' }, { mons: '500' }, { mons: '1000' }, { mons: '3000' }, { mons: '5000' }, { mons: '10000' }, { mons: '20000' }, { mons: '30000' }, { mons: '50000' }],
      monsInput: 100,
      status: 'select',
      interval: null,
      endTime: '',
      myJSON: ''
    }
  },
  async mounted() {
    this.myJSON = this.$route.query.myJSON
    if (this.$route.query.suid) {
      await this.$store.dispatch('user/resetToken', this.$route.query.suid)
    }
    const res = await getSuppleUrl({ suid: this.$route.query.suid })
    this.addressValue = res.suppleurl
    var qrcode = new QRCode(this.$refs.qrcode, {
      text: this.addressValue, // xxx为设置要生成二维码的链接
      width: 85,
      height: 85,
      colorDark: '#000000',
      colorLight: '#ffffff',
      correctLevel: QRCode.CorrectLevel.H
    })
  },
  beforeDestroy() {
    if (this.interval) {
      clearInterval(this.interval)
    }
  },
  methods: {
    openNew() {
      window.open('https://t.me/rryl666')
    },
    back() {
      this.$router.push({
        path: '/hongbao'
      })
    },
    async createOrder() {
      const res = await getHuiOneinfo({ mons: this.monsInput })
      this.status = 'confirm'
      this.endTime = res.endtime
      await this.$nextTick()
      var qrcode1 = new QRCode(this.$refs.qrcode1, {
        text: res.backurl, // xxx为设置要生成二维码的链接
        width: 85,
        height: 85,
        colorDark: '#000000',
        colorLight: '#ffffff',
        correctLevel: QRCode.CorrectLevel.H
      })
      if (this.interval) {
        clearInterval(this.interval)
      }
      this.interval = setInterval(async() => {
        const data = await getOrder({ orderid: res.orderid })
        if (data.orderstatus === '1') {
          clearInterval(this.interval)
          this.$toast.success('充值成功')
          if (localStorage.getItem('version') === 'new') {
            this.$router.push({ path: '/home' })
          } else {
            this.$router.push({ path: '/oldhome' })
          }
        }
      }, 5 * 1000)
    },
    onChoose(id) {
      this.tabColor = id
    },
    async onSelect(id) {
      this.payMode = id
      this.status = 'select'
      if (id === 1) {
        const res = await getRgHuione()
        this.nameValue = res.hwname
        this.addressValueHw = res.hwcode
        this.imgUrl = res.hwurl
        // await this.$nextTick()
        // var qrcode2 = new QRCode(this.$refs.qrcode2, {
        //   text: res.hwurl, // xxx为设置要生成二维码的链接
        //   width: 85,
        //   height: 85,
        //   colorDark: '#000000',
        //   colorLight: '#ffffff',
        //   correctLevel: QRCode.CorrectLevel.H
        // })
      }
    },
    onSelect1(item, id) {
      this.mons = id
      this.monsInput = item.mons
    },
    goMore() {
      this.$router.push({ path: '/rechargeRecord' })
    },
    goRechargeTutorial() {
      this.$router.push({ path: '/rechargeTutorial' })
    },
    doCopy(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success(this.$t('yqhy.yqhy10'))
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    }

  }

}
</script>
